SHIP_RU={1:'Материнский корабль',8:'Добывающая платформа',9:'Штурмовик Радаа',10:'Перехватчик',11:'Линейный крейсер Радаа',13:'Ударный бомбардировщик',14:'Тяжёлый корвет',15:'Штурмовой фрегат Радаа',16:'Носитель',18:'Штурмовой фрегат',19:'Ресурсный контроллер',20:'Ионный фрегат',21:'Тяжёлый крейсер',22:'Фрегат защитного поля (предварительно)',23:'Разведчик',24:'Многопушечный корвет',25:'Мобильный переработчик Радаа',26:'Инженерный корвет',27:'Повреждённый эсминец Радаа',28:'Орудийная платформа Радаа',29:'Лучевой истребитель Радаа',30:'Эсминец',31:'Лазерный корвет Радаа',32:'Эсминец Радаа',33:'Командный корвет Радаа',34:'Тяжёлый ракетный фрегат Радаа',35:'Бомбардировщик Радаа',36:'Гиперврата Радаа',37:'Ракетный корвет Радаа',38:'Ракетный фрегат Радаа',39:'Тяжёлая ракетная платформа Радаа',40:'Навигационный маяк',41:'Верфь Радаа',42:'Технический корабль-заглушка',43:'Верфь',44:'Торговый корабль бентуси',45:'Баррикадный фрегат',46:'Баллистический эсминец',47:'Генератор щита Радаа',48:'Башня Радаа',49:'Сдавшийся эсминец Радаа',50:'Сборщик ресурсов',51:'Станция «Раскол»',52:'Секция станции «Раскол»',53:'Управляющая секция станции «Раскол»',54:'Неподвижный линейный крейсер Радаа'}


def main():
    path=ROOT/'localization/glossary.json'
    if path.exists():entries=json.loads(path.read_text(encoding='utf8'))
    else:
        entries=[]
        seed={
        'Народы и имена':[
            ('Hiigara','Хиигара','Сохранять двойное «ии».'),('Hiigaran','хиигарянин / хиигаряне; хиигарский','Сохранять двойное «ии».'),('Kushan','кушане; кушанский',''),('Novokushan / Neo-Kushan','новокушане; новокушанский','Рабочее название нашей игровой фракции.'),('Taiidan / Taiidani','Таиидан / таиидане; таииданский','Сохранять двойное «ии».'),('Radaa','Радаа; Радаа как определение','Двойное «аа»; не склоняем.'),('Bentusi','бентуси','Народ; с прописной в обращениях/подписи говорящего.'),('Tyrra Soban','Тирра Собан','Женщина; двойное «рр».'),("Karan S’jet","Каран С’Джет",'Женщина.'),('Amma of the Radaa','Амма Радаа','Женщина, мать Гиитана; двойное «мм».'),('Giitan of the Radaa','Гиитан Радаа','Подтверждено Дмитрием: двойное «ии».'),('Chief Engineer Hauk','Главный инженер Хаук','Сын Тирры.'),('Narrator','Рассказчик','HA во вступлении M1; HA в дальнейших беседах также Хаук — смотреть Character, не только суффикс.'),('Fleet Command','Командование флота','Должность/канал; реплики могут принадлежать Тирре или Каран.'),('Fleet Intelligence','Разведка флота',''),('The Beast / BeastWar','Тварь / война с Тварью','Подтверждено Дмитрием; не «Зверь».'),('Daiamid','Дайамид','Правящий совет.'),('Progenitors','Предтечи','Подтверждено Дмитрием: фанатский канон.'),('Sajuuk','Саджуук','Каноническое имя; в используемом фрагменте не вводится как новый участник.')],
        'Места и сюжетные объекты':[
            ('Homeworld','родной мир / Хиигара','По контексту; название серии Homeworld не переводим.'),('Hiigara Proving Grounds','Испытательный полигон Хиигары','M1.'),('Angel Moon','Ангельская Луна','Предварительный вариант; можно уточнить по фанатскому канону.'),('Gybbas','Гиббас','Двойное «бб».'),('Tenhauser','Тенхаузер',''),('Outer Reef','Внешний риф',''),('Shatter Station','станция «Раскол»','Рабочий перевод собственного имени, на согласование.'),('Shatter Station wing','секция станции «Раскол»','Не отдельный новый класс кораблей.'),('The Tower','Башня','Сюжетный объект Радаа.'),('Weapon Architects','создатели оружия','Люди/группа в сюжете, не обязательно название боевого класса.'),('TR-3 Treaty','договор TR-3','Буквы и номер сохранять.'),('Akadet Ferin','Акадет Ферин','Собственное обозначение; не приписывать выдуманное значение.')],
        'Классы и механика':[
            ('Fighter / strike craft','истребитель / ударный аппарат','Общее обозначение strike craft не всегда только истребитель.'),('Strike Group','ударная группа','Игровое объединение нескольких отрядов.'),('Squadron','эскадрилья / отряд','В подсчётах «отряд»: может включать несколько физических корпусов.'),('Corvette','корвет',''),('Frigate','фрегат',''),('Destroyer','эсминец','Не «разрушитель».'),('Heavy Cruiser','тяжёлый крейсер','Класс HW1.'),('Battlecruiser','линейный крейсер','Класс HW2; не смешивать с тяжёлым крейсером.'),('Carrier','носитель',''),('Capital ship','крупный корабль','«Капитал» допустим как наше сокращение в обсуждении, не обязательная подпись UI.'),('Shipyard','верфь',''),('Mothership','Материнский корабль','Как имя единственного корабля в кампании.'),('Resource Units / RU','единицы ресурсов / RU','В таблицах и UI числа RU сохраняем.'),('Research','исследование','Не приписывать платную очередь простому сюжетному открытию.'),('Build unlock','открытие постройки / разрешение строительства',''),('Hyperspace Core','гиперпространственное ядро',''),('Progenitor Core','ядро Предтеч','Термин «Предтечи» подтверждён Дмитрием.'),('Unbound','Освобождённые / Освобождённая','Статус Каран/Тирры; рабочий перевод на согласование.'),('Sensor Sweep','активное сканирование сенсорами',''),('Sensors Manager','карта сенсоров',''),('Resonance silicon','резонансный кремний',''),('Salvage Corvette','абордажный корвет','Название подтверждено Дмитрием. Штатный кушанский корпус HWRM; не полная реализация Engineer Craft.'),('Engineer Craft','инженерный корвет','Исходная роль VR: ремонт/захват/сцепление требуют отдельных адаптеров.'),('Personnel Craft','транспорт с пленными','Контекст M11; не выдумывать доступный игроку новый корпус.'),('Proximity Sensor','датчик приближения',''),('Asteroid / wreckage / container','астероид / обломки / контейнер','')]
        }
        for section,rows in seed.items():
            for en,ru,note in rows:entries.append({'section':section,'en':en,'ru':ru,'note':note,'status':'confirmed_by_user' if en in ('Giitan of the Radaa','The Beast / BeastWar','Progenitors','Progenitor Core','Salvage Corvette') else 'proposed_for_review'})
        for t,r in sorted(q.SHIPS.items()):
            d=r['data'];en=q.STRINGS['en'].get(d['_nameKey']) or d.get('_name') or r['name']
            note='CUT: присутствует определение, это не подтверждение использования в кампании.' if r['name'].startswith('CUT_') else ''
            if t==19:note+=' Кушанский ресурсный контроллер, по уточнению Дмитрия; характеристики уточняем при чтении миссий.'
            if t==22:note+=' Прежняя трактовка как фрегата поддержки снята: ID может отражать старую роль. По предположению Дмитрия — Defense Field Frigate; свойства поля и таииданский/хиигарский аналоги ещё проверить. Не объединять с отдельным типом 45 без проверки.'
            if t==37:note+=' Название/ракетная роль VR сохранены отдельно от таииданского многопушечного визуального аналога.'
            if t==38:note+=' Внешний infiltrator-аналог не означает готовую способность захвата.'
            entries.append({'section':'Корабли и определения VR','en':en,'ru':SHIP_RU[t],'note':note.strip(),'status':'proposed_for_review','ship_type':t,'definition':r['name'],'name_key':d['_nameKey']})
        path.write_text(json.dumps(entries,ensure_ascii=False,indent=2)+'\n',encoding='utf8')
    lines=['# Глоссарий Vast Reaches / HWRM','',
        'Рабочий общий словарь на согласование с Дмитрием. Изменения пользовательского канона имеют приоритет; подтверждённые формы отмечены в примечаниях и статусом confirmed_by_user в JSON. 20 октября приняты: **Защитник**, **стэлс-истребитель**, **минный корвет**, **дронный фрегат**, **тягач**. Названия Новокушан и Новотаиидан, кииты и научные модули собраны в отдельных разделах. В корабельных записях EN обозначает исходный прототип; у новых научных модулей EN пока рабочий перевод, что отмечено в примечаниях. Неподтверждённые названия штатных кораблей остаются на проверке. Двойные гласные в собственных именах сохраняем. Старую игровую локализацию в RAW-документах не исправляем: она нужна как точная цитата.','',
        'Машинный источник этого документа: `localization/glossary.json`; сценарные строки: `localization/ru/campaign.json`. Имена файлов, классов, UCS-ключей и внутренних определений сейчас не переименовываем. Название в таблице не подтверждает совпадение модели, вооружения или способности.','',
        'Разговорные названия из обсуждения не являются автоматически подписями интерфейса. «Пробка», «анти-стэлс», «гравицапа», «ресурсер», «абордажник», «ремонтник» и сокращения фрегатов сохранены как алиасы; в RU приведены полные названия. Отдельно согласованные Защитник, стэлс-истребитель, минный корвет, дронный фрегат и тягач сохраняются.','']
    sections=list(dict.fromkeys(e['section'] for e in entries))
    for section in sections:
        lines+=['## '+section,'','| EN / исходник | RU | Примечание |','|---|---|---|']
        for e in entries:
            if e['section']!=section:continue
            original=e['en']+(f'<br>`{e["definition"]}`' if e.get('definition') else '')
            lines.append('| '+original.replace('|','/')+' | '+e['ru'].replace('|','/')+' | '+e['note'].replace('|','/')+' |')
        lines+=['']
    lines+=['## Как согласовываем','',
        'Можно прислать пары «старое → новое» или поправить RU и примечание в `localization/glossary.json`. После согласования распространяем форму на используемые переводы, подписи персонажей и документы. Исходные EN, старый RU и технические ключи остаются для сверки.','']
    (ROOT/'localization/GLOSSARY.md').write_text('\n'.join(lines),encoding='utf8')
    print(json.dumps({'entries':len(entries),'ship_definitions':sum('definition' in e for e in entries)},ensure_ascii=False))


if __name__=='__main__':main()
